import asyncio

async def main():
    r = await yuki_workspace_read({"path": "start.txt"})
    if not r['ok']:
        return {"err": "start.txt", "r": r}
    start = r['data']['text'].strip().splitlines()[0].strip()
    path = start
    chain = []
    seen = set()
    while True:
        if path in ("END", "", None):
            break
        if path in seen:
            return {"err": "cycle", "path": path}
        seen.add(path)
        rr = await yuki_workspace_read({"path": path})
        if not rr['ok']:
            return {"err": "read", "path": path, "rr": rr}
        d = {}
        for line in rr['data']['text'].splitlines():
            line = line.strip()
            if '=' not in line:
                continue
            k, v = line.split('=', 1)
            d[k.strip()] = v.strip()
        val = int(d['value'])
        chain.append((path, val))
        path = d.get('left', '') if val % 2 == 0 else d.get('right', '')
    exp_lines = [f"{p}\t{v}" for p, v in chain]
    total = sum(v for _, v in chain)
    exp_lines.append(f"TOTAL\t{total}")
    expected = "\n".join(exp_lines) + "\n"
    cr = await yuki_workspace_read({"path": "chain.tsv"})
    actual = cr['data']['text'] if cr['ok'] else None
    chain_ok = (actual == expected)
    audits = []
    for i, (p, v) in enumerate(chain):
        ar = await yuki_workspace_read({"path": f"audit/{i:02d}.txt"})
        a = ar['data']['text'] if ar['ok'] else None
        audits.append((i, v, a))
    bad = [x for x in audits if x[2] != f"{x[1]}\n"]
    return {"start": start, "n": len(chain), "chain": chain, "expected_total": total,
            "chain_ok": chain_ok, "chain_read_ok": cr['ok'],
            "audit_count": len(audits), "audit_all_ok": len(bad) == 0, "bad_audits": bad}

res = await main()
